head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[ModelUtil > M > findInstanceNodes]<br/>Instance 내부에서 XPath 에 해당하는 모든 노드를 배열 형태로 반환합니다.",
    "validation" : [
        "xpath(필수) 파라미터로 반환할 Instance 노드들의 XPath 경로를 설정할 수 있어야 합니다.",
        "xpath 로 찾은 XML Element 노드들의 배열을 반환해야 합니다."
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// 노드 1개를 serialize 하여 한 줄 문자열로 반환 (출력용)
scwin.dumpNode = function (node) {
    if (!node) return "(null)";
    var s = WebSquare.xml.serialize(node);
    return s.replace(/\s+/g, " ").replace(/>\s+</g, "><");
};



scwin.btn_findInstanceNodes_onclick = function () {
    var scenario = par_scenario.getValue();

    if (scenario === "1") {
        // 시나리오 1 : 가이드 예제 - bookstore/book 모든 노드 반환
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 1 : bookstore/book (모든 노드 반환) ──");

        var nodes = WebSquare.ModelUtil.findInstanceNodes("bookstore/book");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 배열 길이 : " + nodes.length);
        for (var i = 0; i < nodes.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("nodes[" + i + "] : " + scwin.dumpNode(nodes[i]));
        }
    } else if (scenario === "2") {
        // 시나리오 2 : 단일 노드 매칭 xpath
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 2 : bookstore/book[1]/title (단일 매칭) ──");

        var nodes = WebSquare.ModelUtil.findInstanceNodes("bookstore/book[1]/title");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 배열 길이 : " + nodes.length);
        for (var i = 0; i < nodes.length; i++) {
            wf_body_bottom.getObj("scwin").setReturnValue("nodes[" + i + "] : " + scwin.dumpNode(nodes[i]));
        }
    } else if (scenario === "3") {
        // 시나리오 3 : 존재하지 않는 xpath → 빈 배열
        wf_body_bottom.getObj("scwin").setReturnValue("── 시나리오 3 : 존재하지 않는 xpath (bookstore/notExist) ──");

        var nodes = WebSquare.ModelUtil.findInstanceNodes("bookstore/notExist");
        wf_body_bottom.getObj("scwin").setReturnValue("반환 배열 길이 : " + nodes.length);
    }
};
